#!/usr/bin/env python3
"""
Round 194o (culprits-tiles-more), 14 October 2026.

- wba_nature.py: every WBA benchmark but the Urban Benchmark, one file each.

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/wba_nature.py': ''}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round194o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round194o_tiles: wrote {path}")
    if not changed:
        print("round194o_tiles: already applied")


if __name__ == "__main__":
    main()
